// Vulnerable to SQL injection:
const query = `SELECT * FROM users WHERE email = '${email}'`;

// Protected with a prepared (parameterized) query:
await prisma.user.findUnique({ where: { email } }); // Prisma escapes automatically

// Another trap: comparing a plaintext password, even with a safe query:
const valid = password === user.password; // WRONG: the password should never be stored in plaintext

// Best practice: compare the bcrypt hash
const valid2 = await bcrypt.compare(password, user.passwordHash); // verifies without ever exposing the plaintext password

// Violation of the single responsibility principle:
class Invoice {
  calculateTotal() { /* ... */ }
  saveToDatabase() { /* ... */ } // shouldn't be here
  sendByEmail() { /* ... */ } // nor this
}
// Better: split into Invoice, InvoiceRepository, InvoiceMailer

// Example of a unit test (Jest/Vitest style)
test('adds two numbers', () => {
  expect(add(2, 3)).toBe(5);
});

test('throws an error on division by zero', () => {
  expect(() => divide(4, 0)).toThrow();
});

test('calls the callback only once', () => {
  const spy = vi.fn();
  callCallback(spy);
  expect(spy).toHaveBeenCalledTimes(1); // checks that no extra call happened
});

// Example of a constructive review comment:
// "This function is 80 lines long and handles 3 different responsibilities.
//  What do you think about splitting it into 2-3 smaller functions, would that make testing easier?"

// To avoid — a vague, judgmental comment:
// "This code is bad, redo it."

// Even better: suggest a concrete direction, not just a question:
// "We could extract the validation into validateOrder() to test it in isolation, what do you think?"
